def compute(vars):
    cost_millions = vars["v1"]
    notes_billions = vars["v2"]
    denominator_millions = notes_billions * 1000
    if denominator_millions == 0:
        return None
    value = cost_millions / denominator_millions * 100
    return {
        "value": value,
        "trace": {
            "cost_millions": cost_millions,
            "notes_millions": denominator_millions,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
